INSERT OR IGNORE INTO supplements (slug, name, name_key, category, form_type, fda_status, safety_status, effectivity, safety, summary, benefits_html, contraindications_html, enhancing_html, interactions_html, why_consider, holistic_html, studies_html, products_json)
VALUES ('vitamin-d3', 'Vitamin D3', 'vitamin d3', 'Vitamin', 'softgel', 'approved', 'safe', 4, 4, 'The sunshine vitamin: supports bone health, immune function and mood, especially when sun exposure is limited.', '<ol><li>Supports calcium absorption and bone density</li><li>Contributes to normal immune function</li><li>May support mood during darker months</li><li>Helps maintain muscle strength in older adults</li><li>Often low in people who work indoors or live far from the equator</li></ol>', '<ol><li>Hypercalcaemia or hyperparathyroidism</li><li>Sarcoidosis and other granulomatous diseases</li><li>Kidney stones or advanced kidney disease: medical advice first</li><li>Very high doses (above 4000 IU daily) without blood tests</li></ol>', '<ol><li>Take with a meal containing fat</li><li>Combine with vitamin K2 and magnesium</li><li>Get 10 to 20 minutes of midday daylight when possible</li><li>Test 25(OH)D levels after 3 months</li></ol>', '<ol><li>Thiazide diuretics (calcium levels)</li><li>Corticosteroids reduce absorption</li><li>Orlistat and cholestyramine reduce absorption</li><li>Digoxin: monitor calcium</li></ol>', 'Low vitamin D status is one of the most common nutrient shortfalls worldwide, particularly in winter and for people who spend most of the day indoors. Supplementing a moderate daily dose is inexpensive, well studied and easy to monitor with a blood test.', '<ul><li>Daylight exposure and outdoor movement remain the primary source</li><li>Fatty fish, egg yolks and fortified foods contribute</li><li>Bone health also depends on resistance training</li><li>Re-test levels seasonally rather than guessing</li></ul>', '<ul><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20D%20supplementation%20to%20prevent%20acute%20respiratory%20tract%20infections%3A%20systematic%20review%20and%20meta-analysis%20of%20individual%20participant%20data" target="_blank" rel="noopener nofollow">Vitamin D supplementation to prevent acute respiratory tract infections: systematic review and meta-analysis of individual participant data — BMJ, 2017</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20D%20and%20risk%20of%20cause%20specific%20death%3A%20systematic%20review%20and%20meta-analysis%20of%20observational%20cohort%20and%20randomised%20intervention%20studies" target="_blank" rel="noopener nofollow">Vitamin D and risk of cause specific death: systematic review and meta-analysis of observational cohort and randomised intervention studies — BMJ, 2014</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Supplemental%20Vitamin%20D%20and%20Incident%20Fractures%20in%20Midlife%20and%20Older%20Adults" target="_blank" rel="noopener nofollow">Supplemental Vitamin D and Incident Fractures in Midlife and Older Adults — New England Journal of Medicine, 2022</a></li></ul>', '[{"name":"Vitamin D3 2000 IU","brand":"Nature Made","url":"https://www.iherb.com/search?kw=Nature%20Made%20Vitamin%20D3%202000%20IU"},{"name":"Vitamin D-3 5000 IU","brand":"NOW Foods","url":"https://www.iherb.com/search?kw=NOW%20Foods%20Vitamin%20D-3%205000%20IU"},{"name":"Vitamin D-1000","brand":"Thorne","url":"https://www.iherb.com/search?kw=Thorne%20Vitamin%20D-1000"},{"name":"Vitamin D3 1000 IU","brand":"Nordic Naturals","url":"https://www.iherb.com/search?kw=Nordic%20Naturals%20Vitamin%20D3%201000%20IU"},{"name":"Vitamin Code Raw D3","brand":"Garden of Life","url":"https://www.iherb.com/search?kw=Garden%20of%20Life%20Vitamin%20Code%20Raw%20D3"}]');

INSERT OR IGNORE INTO supplements (slug, name, name_key, category, form_type, fda_status, safety_status, effectivity, safety, summary, benefits_html, contraindications_html, enhancing_html, interactions_html, why_consider, holistic_html, studies_html, products_json)
VALUES ('magnesium-glycinate', 'Magnesium Glycinate', 'magnesium glycinate', 'Mineral', 'capsule', 'approved', 'safe', 3, 4, 'A gentle, well-absorbed form of magnesium often used for relaxation, sleep quality and muscle recovery.', '<ol><li>Supports normal muscle and nerve function</li><li>May improve sleep quality and relaxation</li><li>Gentle on digestion compared with magnesium oxide or citrate</li><li>Contributes to energy metabolism</li><li>Commonly low in diets rich in processed foods</li></ol>', '<ol><li>Kidney disease or reduced kidney function</li><li>Myasthenia gravis</li><li>Very low heart rate or heart block</li><li>Doses above 350 mg elemental magnesium without medical advice</li></ol>', '<ol><li>Take in the evening for sleep support</li><li>Pair with vitamin B6</li><li>Spread doses through the day if digestion is sensitive</li><li>Combine with vitamin D for bone health</li></ol>', '<ol><li>Antibiotics (tetracyclines, quinolones): separate by 2 to 4 hours</li><li>Bisphosphonates</li><li>Diuretics</li><li>Proton pump inhibitors lower magnesium over time</li></ol>', 'Many adults do not reach the recommended magnesium intake, and stress, intense training and certain medications increase losses. The glycinate form is popular because it is well tolerated and glycine itself has calming properties.', '<ul><li>Leafy greens, nuts, seeds and legumes are rich sources</li><li>Limiting evening screens supports the same sleep goals</li><li>Hydration and electrolytes matter for cramps</li><li>Review medication-related losses with a pharmacist</li></ul>', '<ul><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=The%20effect%20of%20magnesium%20supplementation%20on%20primary%20insomnia%20in%20elderly%3A%20A%20double-blind%20placebo-controlled%20clinical%20trial" target="_blank" rel="noopener nofollow">The effect of magnesium supplementation on primary insomnia in elderly: A double-blind placebo-controlled clinical trial — Journal of Research in Medical Sciences, 2012</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Magnesium%20in%20Prevention%20and%20Therapy" target="_blank" rel="noopener nofollow">Magnesium in Prevention and Therapy — Nutrients, 2015</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Oral%20magnesium%20supplementation%20improves%20insulin%20sensitivity%20and%20metabolic%20control%20in%20type%202%20diabetic%20subjects" target="_blank" rel="noopener nofollow">Oral magnesium supplementation improves insulin sensitivity and metabolic control in type 2 diabetic subjects — Diabetes Care, 2003</a></li></ul>', '[{"name":"High Absorption Magnesium","brand":"Doctor''s Best","url":"https://www.iherb.com/search?kw=Doctor''s%20Best%20High%20Absorption%20Magnesium"},{"name":"Magnesium Glycinate","brand":"Pure Encapsulations","url":"https://www.iherb.com/search?kw=Pure%20Encapsulations%20Magnesium%20Glycinate"},{"name":"Magnesium Glycinate 400","brand":"KAL","url":"https://www.iherb.com/search?kw=KAL%20Magnesium%20Glycinate%20400"},{"name":"Magnesium Bisglycinate","brand":"Thorne","url":"https://www.iherb.com/search?kw=Thorne%20Magnesium%20Bisglycinate"},{"name":"Magnesium Bisglycinate Powder","brand":"NOW Foods","url":"https://www.iherb.com/search?kw=NOW%20Foods%20Magnesium%20Bisglycinate%20Powder"}]');

INSERT OR IGNORE INTO supplements (slug, name, name_key, category, form_type, fda_status, safety_status, effectivity, safety, summary, benefits_html, contraindications_html, enhancing_html, interactions_html, why_consider, holistic_html, studies_html, products_json)
VALUES ('omega-3-fish-oil', 'Omega-3 Fish Oil', 'omega 3 fish oil', 'Fatty Acid', 'softgel', 'approved', 'safe', 4, 4, 'Concentrated EPA and DHA from fish oil, studied for heart, brain and joint health and for lowering triglycerides.', '<ol><li>Supports cardiovascular health and healthy triglyceride levels</li><li>DHA is a key structural fat in the brain and retina</li><li>May ease joint stiffness in inflammatory conditions</li><li>Supports mood and cognitive health with regular intake</li><li>Fills the gap for people who rarely eat oily fish</li></ol>', '<ol><li>Fish or shellfish allergy</li><li>Bleeding disorders or upcoming surgery</li><li>Atrial fibrillation risk at very high doses: discuss with a cardiologist</li><li>Vegans and vegetarians should choose algae-based omega-3 instead</li></ol>', '<ol><li>Take with the largest meal of the day</li><li>Choose products with a third-party purity certificate</li><li>Store in the fridge to prevent oxidation</li><li>Target 250 to 1000 mg combined EPA and DHA daily</li></ol>', '<ol><li>Anticoagulants and antiplatelet drugs</li><li>Blood pressure medication (additive effect)</li><li>Orlistat reduces absorption</li><li>High-dose vitamin E</li></ol>', 'Most people eat far less oily fish than dietary guidelines suggest, so omega-3 intake is often low. Fish oil is among the most researched supplements, with consistent evidence for triglyceride lowering and good overall tolerability.', '<ul><li>Two portions of oily fish a week provide a similar amount</li><li>Fewer ultra-processed foods improve the omega-6 to omega-3 ratio</li><li>Regular aerobic exercise complements cardiovascular benefits</li><li>Sleep and stress management affect inflammation too</li></ul>', '<ul><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Marine%20n-3%20Fatty%20Acids%20and%20Prevention%20of%20Cardiovascular%20Disease%20and%20Cancer" target="_blank" rel="noopener nofollow">Marine n-3 Fatty Acids and Prevention of Cardiovascular Disease and Cancer — New England Journal of Medicine, 2019</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Cardiovascular%20Risk%20Reduction%20with%20Icosapent%20Ethyl%20for%20Hypertriglyceridemia" target="_blank" rel="noopener nofollow">Cardiovascular Risk Reduction with Icosapent Ethyl for Hypertriglyceridemia — New England Journal of Medicine, 2019</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Omega-3%20fatty%20acids%20for%20the%20primary%20and%20secondary%20prevention%20of%20cardiovascular%20disease" target="_blank" rel="noopener nofollow">Omega-3 fatty acids for the primary and secondary prevention of cardiovascular disease — Cochrane Database of Systematic Reviews, 2020</a></li></ul>', '[{"name":"Ultimate Omega","brand":"Nordic Naturals","url":"https://www.iherb.com/search?kw=Nordic%20Naturals%20Ultimate%20Omega"},{"name":"Elite Omega-3 Gems","brand":"Carlson","url":"https://www.iherb.com/search?kw=Carlson%20Elite%20Omega-3%20Gems"},{"name":"Ultra Omega-3","brand":"NOW Foods","url":"https://www.iherb.com/search?kw=NOW%20Foods%20Ultra%20Omega-3"},{"name":"Triple Strength Omega-3","brand":"Sports Research","url":"https://www.iherb.com/search?kw=Sports%20Research%20Triple%20Strength%20Omega-3"},{"name":"Wild Alaskan Fish Oil","brand":"Wiley''s Finest","url":"https://www.iherb.com/search?kw=Wiley''s%20Finest%20Wild%20Alaskan%20Fish%20Oil"}]');

INSERT OR IGNORE INTO supplements (slug, name, name_key, category, form_type, fda_status, safety_status, effectivity, safety, summary, benefits_html, contraindications_html, enhancing_html, interactions_html, why_consider, holistic_html, studies_html, products_json)
VALUES ('probiotic-complex', 'Probiotic Complex', 'probiotic complex', 'Probiotic', 'capsule', 'probably_ok', 'safe', 3, 4, 'Multi-strain live bacteria that support a balanced gut microbiome, digestion and immune resilience.', '<ol><li>Helps restore gut flora after a course of antibiotics</li><li>May reduce bloating and irregular digestion</li><li>Supports immune function via the gut lining</li><li>Some strains shorten infectious diarrhoea</li><li>Can support regularity during travel or diet changes</li></ol>', '<ol><li>Severely weakened immune system or chemotherapy</li><li>Central venous catheters</li><li>Short bowel syndrome</li><li>Critically ill patients: hospital guidance only</li></ol>', '<ol><li>Take consistently at the same time each day</li><li>Pair with prebiotic fibre such as inulin or oats</li><li>Keep refrigerated if the label requires it</li><li>Allow 4 weeks before judging results</li></ol>', '<ol><li>Antibiotics: separate by at least 2 hours</li><li>Immunosuppressants</li><li>Antifungal medication</li><li>Heavy alcohol use reduces benefit</li></ol>', 'Modern diets, stress and antibiotics can all disrupt the gut microbiome. A well-formulated multi-strain probiotic is a low-risk way to support digestion, particularly during and after antibiotic treatment or travel.', '<ul><li>Fermented foods such as yoghurt, kefir, kimchi and sauerkraut serve the same goal</li><li>Fibre diversity matters more than any single capsule</li><li>Sleep and stress strongly influence gut health</li><li>Chewing slowly and regular meals aid digestion</li></ul>', '<ul><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Probiotics%20for%20the%20prevention%20of%20Clostridium%20difficile-associated%20diarrhea%20in%20adults%20and%20children" target="_blank" rel="noopener nofollow">Probiotics for the prevention of Clostridium difficile-associated diarrhea in adults and children — Cochrane Database of Systematic Reviews, 2017</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Probiotics%20for%20the%20prevention%20of%20pediatric%20antibiotic-associated%20diarrhea" target="_blank" rel="noopener nofollow">Probiotics for the prevention of pediatric antibiotic-associated diarrhea — Cochrane Database of Systematic Reviews, 2019</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=The%20International%20Scientific%20Association%20for%20Probiotics%20and%20Prebiotics%20consensus%20statement%20on%20the%20scope%20and%20appropriate%20use%20of%20the%20term%20probiotic" target="_blank" rel="noopener nofollow">The International Scientific Association for Probiotics and Prebiotics consensus statement on the scope and appropriate use of the term probiotic — Nature Reviews Gastroenterology &amp; Hepatology, 2014</a></li></ul>', '[{"name":"Digestive Daily Probiotic","brand":"Culturelle","url":"https://www.iherb.com/search?kw=Culturelle%20Digestive%20Daily%20Probiotic"},{"name":"Dr. Formulated Probiotics Once Daily","brand":"Garden of Life","url":"https://www.iherb.com/search?kw=Garden%20of%20Life%20Dr.%20Formulated%20Probiotics%20Once%20Daily"},{"name":"Probiotic Supplement","brand":"Align","url":"https://www.iherb.com/search?kw=Align%20Probiotic%20Supplement"},{"name":"DS-01 Daily Synbiotic","brand":"Seed","url":"https://www.iherb.com/search?kw=Seed%20DS-01%20Daily%20Synbiotic"},{"name":"Ultimate Flora","brand":"Renew Life","url":"https://www.iherb.com/search?kw=Renew%20Life%20Ultimate%20Flora"}]');

INSERT OR IGNORE INTO supplements (slug, name, name_key, category, form_type, fda_status, safety_status, effectivity, safety, summary, benefits_html, contraindications_html, enhancing_html, interactions_html, why_consider, holistic_html, studies_html, products_json)
VALUES ('ashwagandha', 'Ashwagandha', 'ashwagandha', 'Adaptogen', 'capsule', 'probably_ok', 'ok', 3, 3, 'A traditional Ayurvedic adaptogen studied for stress, sleep quality and cortisol balance.', '<ol><li>May reduce perceived stress and anxiety scores</li><li>Can improve sleep onset and quality</li><li>Studied for modest gains in strength and recovery</li><li>May support healthy testosterone levels in men</li><li>Traditionally used to support energy and resilience</li></ol>', '<ol><li>Pregnancy and breastfeeding</li><li>Autoimmune conditions such as lupus or rheumatoid arthritis</li><li>Thyroid disorders: may raise thyroid hormone levels</li><li>Liver disease or a history of drug-induced liver injury</li><li>Before surgery because of sedative effects</li></ol>', '<ol><li>Use a standardised root extract such as KSM-66 or Sensoril</li><li>Take in the evening if drowsiness occurs</li><li>Combine with consistent sleep timing</li><li>Cycle 8 to 12 weeks on, then reassess</li></ol>', '<ol><li>Sedatives and sleep medication</li><li>Thyroid hormone medication</li><li>Immunosuppressants</li><li>Blood sugar and blood pressure medication (additive effects)</li></ol>', 'If chronic stress and poor sleep are your main concerns, ashwagandha has some of the better human trial data among herbal adaptogens. Effects are modest and build over several weeks, and it should be paused if any liver symptoms appear.', '<ul><li>Daily movement, daylight and breath-work lower stress hormones too</li><li>Caffeine after noon undermines the sleep goal</li><li>Protein and strength training amplify recovery benefits</li><li>Track mood and sleep for 6 weeks to judge impact</li></ul>', '<ul><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=An%20investigation%20into%20the%20stress-relieving%20and%20pharmacological%20actions%20of%20an%20ashwagandha%20(Withania%20somnifera)%20extract" target="_blank" rel="noopener nofollow">An investigation into the stress-relieving and pharmacological actions of an ashwagandha (Withania somnifera) extract — Medicine (Baltimore), 2019</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Efficacy%20and%20Safety%20of%20Ashwagandha%20(Withania%20somnifera)%20Root%20Extract%20in%20Insomnia%20and%20Anxiety%3A%20A%20Double-blind%2C%20Randomized%2C%20Placebo-controlled%20Study" target="_blank" rel="noopener nofollow">Efficacy and Safety of Ashwagandha (Withania somnifera) Root Extract in Insomnia and Anxiety: A Double-blind, Randomized, Placebo-controlled Study — Cureus, 2019</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Ashwagandha-induced%20liver%20injury%3A%20A%20case%20series%20from%20Iceland%20and%20the%20US%20Drug-Induced%20Liver%20Injury%20Network" target="_blank" rel="noopener nofollow">Ashwagandha-induced liver injury: A case series from Iceland and the US Drug-Induced Liver Injury Network — Liver International, 2020</a></li></ul>', '[{"name":"KSM-66 Ashwagandha","brand":"Jarrow Formulas","url":"https://www.iherb.com/search?kw=Jarrow%20Formulas%20KSM-66%20Ashwagandha"},{"name":"Ashwagandha Root","brand":"Gaia Herbs","url":"https://www.iherb.com/search?kw=Gaia%20Herbs%20Ashwagandha%20Root"},{"name":"Organic Ashwagandha","brand":"Himalaya","url":"https://www.iherb.com/search?kw=Himalaya%20Organic%20Ashwagandha"},{"name":"Ashwagandha 450 mg","brand":"NOW Foods","url":"https://www.iherb.com/search?kw=NOW%20Foods%20Ashwagandha%20450%20mg"},{"name":"Ashwagandha","brand":"Nature''s Way","url":"https://www.iherb.com/search?kw=Nature''s%20Way%20Ashwagandha"}]');

INSERT OR IGNORE INTO supplements (slug, name, name_key, category, form_type, fda_status, safety_status, effectivity, safety, summary, benefits_html, contraindications_html, enhancing_html, interactions_html, why_consider, holistic_html, studies_html, products_json)
VALUES ('creatine-monohydrate', 'Creatine Monohydrate', 'creatine monohydrate', 'Amino Acid', 'powder', 'approved', 'safe', 5, 5, 'The most researched sports supplement: improves strength and power output and may support brain energy.', '<ol><li>Increases strength and high-intensity performance</li><li>Supports lean muscle gain alongside resistance training</li><li>May improve short-term memory and mental fatigue</li><li>Helps preserve muscle in older adults</li><li>Inexpensive with decades of safety data</li></ol>', '<ol><li>Pre-existing kidney disease: medical advice first</li><li>Bipolar disorder: discuss with a psychiatrist</li><li>Under 18 without supervision</li><li>Endurance events in heat without adequate fluid intake</li></ol>', '<ol><li>3 to 5 g daily, no loading phase needed</li><li>Take with carbohydrates or a meal</li><li>Stay well hydrated</li><li>Consistency matters more than timing</li></ol>', '<ol><li>NSAIDs and other kidney-stressing drugs</li><li>Diuretics</li><li>Very high caffeine doses may blunt the effect</li><li>Nephrotoxic medication</li></ol>', 'Creatine monohydrate has hundreds of trials behind it and is effective for almost everyone who trains, including women and older adults. It also shows emerging benefits for cognition, especially in vegetarians who get little creatine from food.', '<ul><li>Red meat and fish provide 1 to 2 g per day naturally</li><li>Progressive strength training turns creatine into results</li><li>Sleep drives recovery and adaptation</li><li>A small weight increase from water retention is normal</li></ul>', '<ul><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=International%20Society%20of%20Sports%20Nutrition%20position%20stand%3A%20safety%20and%20efficacy%20of%20creatine%20supplementation%20in%20exercise%2C%20sport%2C%20and%20medicine" target="_blank" rel="noopener nofollow">International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine — Journal of the International Society of Sports Nutrition, 2017</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Effects%20of%20creatine%20supplementation%20on%20cognitive%20function%20of%20healthy%20individuals%3A%20A%20systematic%20review%20of%20randomized%20controlled%20trials" target="_blank" rel="noopener nofollow">Effects of creatine supplementation on cognitive function of healthy individuals: A systematic review of randomized controlled trials — Experimental Gerontology, 2018</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Creatine%20Supplementation%20and%20Brain%20Health" target="_blank" rel="noopener nofollow">Creatine Supplementation and Brain Health — Nutrients, 2021</a></li></ul>', '[{"name":"Micronized Creatine Powder","brand":"Optimum Nutrition","url":"https://www.iherb.com/search?kw=Optimum%20Nutrition%20Micronized%20Creatine%20Powder"},{"name":"Creatine","brand":"Thorne","url":"https://www.iherb.com/search?kw=Thorne%20Creatine"},{"name":"Klean Creatine","brand":"Klean Athlete","url":"https://www.iherb.com/search?kw=Klean%20Athlete%20Klean%20Creatine"},{"name":"Creatine Monohydrate","brand":"BulkSupplements","url":"https://www.iherb.com/search?kw=BulkSupplements%20Creatine%20Monohydrate"},{"name":"Creatine Monohydrate","brand":"Myprotein","url":"https://www.iherb.com/search?kw=Myprotein%20Creatine%20Monohydrate"}]');

INSERT OR IGNORE INTO supplements (slug, name, name_key, category, form_type, fda_status, safety_status, effectivity, safety, summary, benefits_html, contraindications_html, enhancing_html, interactions_html, why_consider, holistic_html, studies_html, products_json)
VALUES ('vitamin-b12', 'Vitamin B12', 'vitamin b12', 'Vitamin', 'tablet', 'approved', 'safe', 4, 5, 'Essential for red blood cells, nerve function and energy metabolism, and a must-have on vegan and plant-based diets.', '<ol><li>Prevents B12 deficiency anaemia</li><li>Supports nerve health and cognition</li><li>Helps convert food into energy</li><li>Essential on vegan and vegetarian diets</li><li>Absorption declines with age, so supplementation helps older adults</li></ol>', '<ol><li>Leber hereditary optic neuropathy</li><li>Cobalt or cobalamin allergy</li><li>Unexplained anaemia should be investigated before supplementing</li><li>Kidney disease with high-dose cyanocobalamin: prefer methylcobalamin</li></ol>', '<ol><li>Sublingual tablets help if stomach acid is low</li><li>Take with folate and B6 for homocysteine support</li><li>A daily low dose or a weekly higher dose both work</li><li>Check blood levels if fatigue persists</li></ol>', '<ol><li>Metformin lowers B12 absorption</li><li>Proton pump inhibitors and H2 blockers</li><li>Colchicine</li><li>Nitrous oxide inactivates B12</li></ol>', 'Vitamin B12 is found almost exclusively in animal foods, so anyone eating mostly plants should supplement it. Deficiency develops slowly and can cause fatigue, tingling and memory issues that are easy to prevent.', '<ul><li>Eggs, dairy, fish and fortified plant milks are dietary sources</li><li>Energy also depends on iron, sleep and hydration</li><li>Regular blood tests on long-term metformin</li><li>Pair with a balanced B-complex if the diet is restricted</li></ul>', '<ul><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20B12%20deficiency" target="_blank" rel="noopener nofollow">Vitamin B12 deficiency — BMJ, 2014</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Oral%20vitamin%20B12%20versus%20intramuscular%20vitamin%20B12%20for%20vitamin%20B12%20deficiency" target="_blank" rel="noopener nofollow">Oral vitamin B12 versus intramuscular vitamin B12 for vitamin B12 deficiency — Cochrane Database of Systematic Reviews, 2018</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=How%20prevalent%20is%20vitamin%20B12%20deficiency%20among%20vegetarians%3F" target="_blank" rel="noopener nofollow">How prevalent is vitamin B12 deficiency among vegetarians? — Nutrition Reviews, 2013</a></li></ul>', '[{"name":"Methyl B-12 1000 mcg","brand":"Jarrow Formulas","url":"https://www.iherb.com/search?kw=Jarrow%20Formulas%20Methyl%20B-12%201000%20mcg"},{"name":"Vitamin B12 1000 mcg","brand":"Nature Made","url":"https://www.iherb.com/search?kw=Nature%20Made%20Vitamin%20B12%201000%20mcg"},{"name":"Vitamin Code Raw B-12","brand":"Garden of Life","url":"https://www.iherb.com/search?kw=Garden%20of%20Life%20Vitamin%20Code%20Raw%20B-12"},{"name":"Methylcobalamin 1000 mcg","brand":"Solgar","url":"https://www.iherb.com/search?kw=Solgar%20Methylcobalamin%201000%20mcg"},{"name":"Methyl B-12","brand":"NOW Foods","url":"https://www.iherb.com/search?kw=NOW%20Foods%20Methyl%20B-12"}]');

INSERT OR IGNORE INTO supplements (slug, name, name_key, category, form_type, fda_status, safety_status, effectivity, safety, summary, benefits_html, contraindications_html, enhancing_html, interactions_html, why_consider, holistic_html, studies_html, products_json)
VALUES ('zinc-picolinate', 'Zinc Picolinate', 'zinc picolinate', 'Mineral', 'capsule', 'approved', 'ok', 3, 3, 'A well-absorbed zinc form that supports immune defence, skin health and wound healing.', '<ol><li>Supports normal immune function</li><li>Involved in skin repair and acne management</li><li>Supports taste, smell and appetite</li><li>Needed for testosterone production and fertility</li><li>May shorten the common cold when started early</li></ol>', '<ol><li>Haemochromatosis or copper deficiency</li><li>Long-term doses above 40 mg daily</li><li>Pregnancy at high doses</li><li>Nausea on an empty stomach: take with food</li></ol>', '<ol><li>Take with food to avoid nausea</li><li>Balance with 1 to 2 mg copper for long-term use</li><li>Avoid taking with high-phytate meals</li><li>Short courses during infections, lower doses long term</li></ol>', '<ol><li>Antibiotics (quinolones, tetracyclines): separate by 2 hours</li><li>Penicillamine</li><li>Diuretics increase zinc loss</li><li>Iron and calcium supplements compete for absorption</li></ol>', 'Zinc requirements rise with intense training, vegetarian diets and periods of illness, and mild shortfalls are common. The picolinate form is well absorbed, making it a sensible choice for short immune-support courses.', '<ul><li>Oysters, red meat, pumpkin seeds and legumes are good sources</li><li>Sleep and hand hygiene remain the first line of immune defence</li><li>Skin health also depends on hydration and sun protection</li><li>Avoid megadoses: more is not better with zinc</li></ul>', '<ul><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Zinc%20for%20the%20common%20cold" target="_blank" rel="noopener nofollow">Zinc for the common cold — Cochrane Database of Systematic Reviews, 2013</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Zinc%20in%20Human%20Health%3A%20Effect%20of%20Zinc%20on%20Immune%20Cells" target="_blank" rel="noopener nofollow">Zinc in Human Health: Effect of Zinc on Immune Cells — Molecular Medicine, 2008</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/?term=Discovery%20of%20human%20zinc%20deficiency%3A%20its%20impact%20on%20human%20health%20and%20disease" target="_blank" rel="noopener nofollow">Discovery of human zinc deficiency: its impact on human health and disease — Advances in Nutrition, 2013</a></li></ul>', '[{"name":"Zinc Picolinate 30 mg","brand":"Thorne","url":"https://www.iherb.com/search?kw=Thorne%20Zinc%20Picolinate%2030%20mg"},{"name":"Zinc Picolinate 50 mg","brand":"NOW Foods","url":"https://www.iherb.com/search?kw=NOW%20Foods%20Zinc%20Picolinate%2050%20mg"},{"name":"Zinc Picolinate 22 mg","brand":"Solgar","url":"https://www.iherb.com/search?kw=Solgar%20Zinc%20Picolinate%2022%20mg"},{"name":"Zinc 30","brand":"Pure Encapsulations","url":"https://www.iherb.com/search?kw=Pure%20Encapsulations%20Zinc%2030"},{"name":"Zinc Picolinate","brand":"Nature''s Way","url":"https://www.iherb.com/search?kw=Nature''s%20Way%20Zinc%20Picolinate"}]');
